-- >>> 0021_test_runs.sql
-- =============================================================================
-- 0021_test_runs.sql — test the draft before publishing it
--
-- NOT APPLIED. Owner approval required before this reaches any Supabase project.
-- Requires 0020 (it calls org_entitlements()).
--
-- WHY
--
-- PRD.md section 5 asks for a playground that tests an agent before it is
-- published. Until now a run could only execute a PUBLISHED version, so the
-- only way to try a change was to publish it - which puts it live.
--
-- HOW IT STAYS SAFE
--
--   * The run still pins an immutable configuration (CLAUDE.md rule 8). The
--     draft itself is mutable, so start_test_run() SNAPSHOTS its config_json
--     into runs.config_snapshot at dispatch, and the executor runs the
--     snapshot. Editing the draft afterwards cannot change what a test ran.
--   * The snapshot is read from the database, never accepted from the caller:
--     a client calling the RPC directly cannot smuggle in a configuration.
--   * Every limit start_run applies applies here too, read under the same
--     organisation lock: suspension, entitlements (runs allowed, concurrency,
--     monthly budget) and the budget reservation. A test run costs money like
--     any other and is accounted like any other.
--   * runs.is_test marks it, so the product can label it and reports can tell
--     tests from production use.
--
-- DATA IT CHANGES: adds two columns to runs (existing rows: is_test = false,
-- config_snapshot = null, which satisfies the new check). No row is updated.
-- =============================================================================

alter table public.runs
  add column is_test boolean not null default false,
  add column config_snapshot jsonb;

alter table public.runs
  add constraint runs_test_has_snapshot check (is_test = (config_snapshot is not null));

create or replace function public.start_test_run(
  p_agent_id uuid,
  p_input    jsonb default '{}'::jsonb
)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_uid       uuid := (select auth.uid());
  v_org_id    uuid;
  v_status    public.agent_status;
  v_draft     uuid;
  v_config    jsonb;
  v_budget    bigint;
  v_cap       bigint;
  v_org_state public.org_status;
  v_period    date := public.current_usage_period();
  v_spent     bigint;
  v_reserved  bigint;
  v_run_id    uuid;
  v_ent       jsonb;
  v_live      integer;
begin
  if v_uid is null then
    raise exception 'AUTH_REQUIRED' using errcode = 'insufficient_privilege';
  end if;

  select a.org_id, a.status into v_org_id, v_status
  from public.agents a
  where a.id = p_agent_id;

  if v_org_id is null
     or not public.has_org_role(
          v_org_id, array['owner', 'admin', 'member']::public.org_role[]
        ) then
    raise exception 'ORG_ACCESS_DENIED' using errcode = 'insufficient_privilege';
  end if;

  if v_status = 'archived' then
    raise exception 'AGENT_ARCHIVED' using errcode = 'invalid_parameter_value';
  end if;

  select v.id, v.config_json into v_draft, v_config
  from public.agent_versions v
  where v.agent_id = p_agent_id and v.published_at is null;

  if v_draft is null then
    raise exception 'AGENT_VERSION_MISSING' using errcode = 'no_data_found';
  end if;

  -- The database's floor: the fields a run cannot start without. The
  -- application validates the full schema first and names what is missing.
  if coalesce(btrim(v_config ->> 'role'), '') = ''
     or length(coalesce(btrim(v_config ->> 'instructions'), '')) < 10
     or coalesce(v_config ->> 'provider', '') = ''
     or coalesce(v_config ->> 'model', '') = '' then
    raise exception 'AGENT_CONFIG_INVALID' using errcode = 'invalid_parameter_value';
  end if;

  select o.status into v_org_state
  from public.organizations o
  where o.id = v_org_id
  for update;

  if v_org_state = 'suspended' then
    raise exception 'ORG_SUSPENDED' using errcode = 'insufficient_privilege';
  end if;

  v_ent := public.org_entitlements(v_org_id);

  if not coalesce((v_ent ->> 'runsAllowed')::boolean, false) then
    raise exception 'SUBSCRIPTION_INACTIVE' using errcode = 'insufficient_privilege';
  end if;

  if (v_ent ->> 'maxConcurrentRuns') is not null then
    select count(*) into v_live
    from public.runs r
    where r.org_id = v_org_id and r.status in ('queued', 'running', 'awaiting_approval');
    if v_live >= (v_ent ->> 'maxConcurrentRuns')::integer then
      raise exception 'RUN_CONCURRENCY_LIMIT' using errcode = 'insufficient_resources';
    end if;
  end if;

  v_cap := (v_ent ->> 'monthlyModelBudgetUsdMicros')::bigint;

  begin
    v_budget := (v_config ->> 'maxSpendUsdMicros')::bigint;
  exception when others then
    v_budget := null;
  end;
  if v_budget is null or v_budget <= 0 then
    raise exception 'AGENT_CONFIG_INVALID' using errcode = 'invalid_parameter_value';
  end if;

  insert into public.usage_periods (org_id, period_start)
  values (v_org_id, v_period)
  on conflict (org_id, period_start) do nothing;

  select p.spent_usd_micros, p.reserved_usd_micros into v_spent, v_reserved
  from public.usage_periods p
  where p.org_id = v_org_id and p.period_start = v_period;

  if v_spent + v_reserved + v_budget > v_cap then
    raise exception 'USAGE_LIMIT_REACHED' using errcode = 'insufficient_resources';
  end if;

  insert into public.runs
    (org_id, agent_id, agent_version_id, initiator_user_id, input_json,
     budget_usd_micros, is_test, config_snapshot)
  values
    (v_org_id, p_agent_id, v_draft, v_uid, coalesce(p_input, '{}'::jsonb),
     v_budget, true, v_config)
  returning id into v_run_id;

  insert into public.usage_reservations (org_id, run_id, max_usd_micros, expires_at)
  values (v_org_id, v_run_id, v_budget, now() + interval '1 hour');

  update public.usage_periods
  set reserved_usd_micros = reserved_usd_micros + v_budget, updated_at = now()
  where org_id = v_org_id and period_start = v_period;

  perform public.log_audit(
    v_org_id, 'user', 'run.test_started', 'run', v_run_id,
    jsonb_build_object('agent_id', p_agent_id, 'draft_version_id', v_draft,
                       'budget_usd_micros', v_budget)
  );

  return jsonb_build_object('run_id', v_run_id, 'reused', false);
end;
$$;

revoke execute on function public.start_test_run(uuid, jsonb) from public, anon;
grant execute on function public.start_test_run(uuid, jsonb) to authenticated;

-- <<< 0021_test_runs.sql

-- >>> 0022_knowledge.sql
-- =============================================================================
-- 0022_knowledge.sql — organisation knowledge sources
--
-- NOT APPLIED. Owner approval required before this reaches any Supabase project.
-- Requires 0020 (the knowledge-base count is an entitlement).
--
-- WHAT
--
--   knowledge_bases      named collections, per organisation
--   knowledge_documents  one uploaded or pasted text/markdown document
--   knowledge_chunks     the document split for retrieval, with a full-text index
--
-- Text is stored in Postgres, not in object storage: v1 accepts plain text and
-- markdown only (no PDF parsing, no executable or HTML rendering), bounded at
-- 512 KB per document. Retrieval is Postgres full-text search - no embedding
-- provider, no extra data processor, no extra cost.
--
-- ISOLATION
--
-- Every row carries org_id; composite foreign keys keep a document inside its
-- knowledge base's organisation and a chunk inside its document's. RLS lets
-- members of the organisation read; writes go through two functions that
-- check the role and, for new knowledge bases, the plan's limit. Chunks are
-- never written directly by any customer role.
--
-- DATA IT CHANGES: none. New tables and functions only.
-- =============================================================================

create table public.knowledge_bases (
  id          uuid primary key default gen_random_uuid(),
  org_id      uuid not null references public.organizations (id) on delete cascade,
  name        text not null check (length(btrim(name)) between 2 and 120),
  description text check (description is null or length(description) <= 500),
  created_by  uuid references auth.users (id) on delete set null,
  created_at  timestamptz not null default now(),
  constraint knowledge_bases_org_id_key unique (org_id, id)
);
create index knowledge_bases_org_idx on public.knowledge_bases (org_id, created_at desc);

create table public.knowledge_documents (
  id                uuid primary key default gen_random_uuid(),
  org_id            uuid not null,
  knowledge_base_id uuid not null,
  title             text not null check (length(btrim(title)) between 1 and 200),
  source_type       text not null check (source_type in ('upload', 'paste')),
  mime_type         text not null check (mime_type in ('text/plain', 'text/markdown')),
  byte_size         integer not null check (byte_size between 1 and 524288),
  content_sha256    bytea not null check (length(content_sha256) = 32),
  chunk_count       integer not null check (chunk_count between 1 and 1000),
  created_by        uuid references auth.users (id) on delete set null,
  created_at        timestamptz not null default now(),
  constraint knowledge_documents_kb_fk
    foreign key (org_id, knowledge_base_id)
    references public.knowledge_bases (org_id, id) on delete cascade,
  constraint knowledge_documents_org_id_key unique (org_id, id),
  -- The same file twice in one knowledge base is a mistake, not a feature.
  constraint knowledge_documents_dedupe unique (knowledge_base_id, content_sha256)
);
create index knowledge_documents_kb_idx
  on public.knowledge_documents (org_id, knowledge_base_id, created_at desc);

create table public.knowledge_chunks (
  id                uuid primary key default gen_random_uuid(),
  org_id            uuid not null,
  knowledge_base_id uuid not null,
  document_id       uuid not null,
  chunk_index       integer not null check (chunk_index >= 0),
  content           text not null check (length(content) between 1 and 4000),
  -- 'simple' configuration: no language-specific stemming, which Postgres does
  -- not ship for Hebrew; words match as written.
  tsv               tsvector generated always as (to_tsvector('simple', content)) stored,
  constraint knowledge_chunks_doc_fk
    foreign key (org_id, document_id)
    references public.knowledge_documents (org_id, id) on delete cascade,
  constraint knowledge_chunks_kb_fk
    foreign key (org_id, knowledge_base_id)
    references public.knowledge_bases (org_id, id) on delete cascade,
  constraint knowledge_chunks_doc_index_key unique (document_id, chunk_index)
);
create index knowledge_chunks_tsv_idx on public.knowledge_chunks using gin (tsv);
create index knowledge_chunks_org_kb_idx on public.knowledge_chunks (org_id, knowledge_base_id);

-- -----------------------------------------------------------------------------
-- RLS
-- -----------------------------------------------------------------------------

alter table public.knowledge_bases enable row level security;
alter table public.knowledge_documents enable row level security;
alter table public.knowledge_chunks enable row level security;

revoke all on public.knowledge_bases, public.knowledge_documents, public.knowledge_chunks
  from anon, authenticated;
grant select on public.knowledge_bases, public.knowledge_documents, public.knowledge_chunks
  to authenticated;
-- Removing knowledge: owner and admin, through RLS (cascades to chunks).
grant delete on public.knowledge_bases, public.knowledge_documents to authenticated;
grant select on public.knowledge_bases, public.knowledge_documents, public.knowledge_chunks
  to service_role;

create policy knowledge_bases_read on public.knowledge_bases for select to authenticated
  using (public.is_org_member(org_id));
create policy knowledge_documents_read on public.knowledge_documents for select to authenticated
  using (public.is_org_member(org_id));
create policy knowledge_chunks_read on public.knowledge_chunks for select to authenticated
  using (public.is_org_member(org_id));

create policy knowledge_bases_delete on public.knowledge_bases for delete to authenticated
  using (public.has_org_role(org_id, array['owner', 'admin']::public.org_role[]));
create policy knowledge_documents_delete on public.knowledge_documents for delete to authenticated
  using (public.has_org_role(org_id, array['owner', 'admin']::public.org_role[]));

-- -----------------------------------------------------------------------------
-- writes
-- -----------------------------------------------------------------------------

create or replace function public.create_knowledge_base(
  p_org_id      uuid,
  p_name        text,
  p_description text default null
)
returns uuid
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_uid   uuid := (select auth.uid());
  v_limit bigint;
  v_count integer;
  v_id    uuid;
begin
  if v_uid is null then
    raise exception 'AUTH_REQUIRED' using errcode = 'insufficient_privilege';
  end if;
  if not public.has_org_role(p_org_id, array['owner', 'admin', 'member']::public.org_role[]) then
    raise exception 'ORG_ACCESS_DENIED' using errcode = 'insufficient_privilege';
  end if;

  -- Serialise against concurrent creations so two cannot both slip under the limit.
  perform 1 from public.organizations o where o.id = p_org_id for update;

  v_limit := (public.org_entitlements(p_org_id) ->> 'knowledgeBases')::bigint;
  if v_limit is not null then
    select count(*) into v_count from public.knowledge_bases kb where kb.org_id = p_org_id;
    if v_count >= v_limit then
      raise exception 'PLAN_FEATURE_UNAVAILABLE' using errcode = 'insufficient_resources',
        detail = 'knowledge base limit reached for this plan';
    end if;
  end if;

  insert into public.knowledge_bases (org_id, name, description, created_by)
  values (p_org_id, btrim(p_name), nullif(btrim(coalesce(p_description, '')), ''), v_uid)
  returning id into v_id;

  perform public.log_audit(p_org_id, 'user', 'knowledge_base.created', 'knowledge_base', v_id,
                           '{}'::jsonb);
  return v_id;
end;
$$;

-- The document and all its chunks in one transaction: a half-indexed document
-- would answer some questions and silently miss others.
create or replace function public.add_knowledge_document(
  p_knowledge_base_id uuid,
  p_title             text,
  p_source_type       text,
  p_mime_type         text,
  p_byte_size         integer,
  p_content_sha256    bytea,
  p_chunks            text[]
)
returns uuid
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_uid    uuid := (select auth.uid());
  v_org_id uuid;
  v_doc    uuid;
  v_n      integer := coalesce(array_length(p_chunks, 1), 0);
  i        integer;
begin
  if v_uid is null then
    raise exception 'AUTH_REQUIRED' using errcode = 'insufficient_privilege';
  end if;

  select kb.org_id into v_org_id from public.knowledge_bases kb where kb.id = p_knowledge_base_id;
  if v_org_id is null
     or not public.has_org_role(v_org_id, array['owner', 'admin', 'member']::public.org_role[]) then
    raise exception 'ORG_ACCESS_DENIED' using errcode = 'insufficient_privilege';
  end if;

  if v_n = 0 or v_n > 1000 then
    raise exception 'VALIDATION_FAILED' using errcode = 'invalid_parameter_value';
  end if;

  insert into public.knowledge_documents
    (org_id, knowledge_base_id, title, source_type, mime_type, byte_size, content_sha256,
     chunk_count, created_by)
  values
    (v_org_id, p_knowledge_base_id, btrim(p_title), p_source_type, p_mime_type, p_byte_size,
     p_content_sha256, v_n, v_uid)
  returning id into v_doc;

  for i in 1 .. v_n loop
    insert into public.knowledge_chunks (org_id, knowledge_base_id, document_id, chunk_index, content)
    values (v_org_id, p_knowledge_base_id, v_doc, i - 1, p_chunks[i]);
  end loop;

  perform public.log_audit(v_org_id, 'user', 'knowledge_document.added', 'knowledge_document', v_doc,
                           jsonb_build_object('knowledge_base_id', p_knowledge_base_id,
                                              'chunks', v_n, 'bytes', p_byte_size));
  return v_doc;
end;
$$;

revoke execute on function public.create_knowledge_base(uuid, text, text) from public, anon;
grant execute on function public.create_knowledge_base(uuid, text, text) to authenticated;
revoke execute on function public.add_knowledge_document(uuid, text, text, text, integer, bytea, text[])
  from public, anon;
grant execute on function public.add_knowledge_document(uuid, text, text, text, integer, bytea, text[])
  to authenticated;

-- <<< 0022_knowledge.sql

-- ---- post-check ------------------------------------------------------------
do $$
declare
  v_missing text;
  v_open    text;
begin
  select string_agg(t, ', ') into v_missing
  from unnest(array[
    'public.plans', 'public.plan_versions', 'public.subscriptions',
    'public.subscription_events', 'public.billing_webhook_events',
    'public.entitlement_overrides', 'public.knowledge_bases',
    'public.knowledge_documents', 'public.knowledge_chunks'
  ]) as t
  where to_regclass(t) is null;
  if v_missing is not null then
    raise exception 'post-check: missing tables: %', v_missing;
  end if;

  if to_regprocedure('public.effective_entitlements(uuid)') is null
     or to_regprocedure('public.start_test_run(uuid, jsonb)') is null
     or to_regprocedure('public.add_knowledge_document(uuid, text, text, text, integer, bytea, text[])') is null then
    raise exception 'post-check: an expected function was not created';
  end if;

  if (select count(*) from public.plan_versions) <> 3 then
    raise exception 'post-check: expected exactly 3 plan versions';
  end if;

  select string_agg(p.oid::regprocedure::text, ', ') into v_open
  from pg_proc p
  join pg_namespace n on n.oid = p.pronamespace
  where n.nspname = 'public'
    and p.prorettype <> 'pg_catalog.trigger'::regtype
    and has_function_privilege('anon', p.oid, 'EXECUTE');
  if v_open is not null then
    raise exception 'post-check: anon can execute: %', v_open;
  end if;
end;
$$;

commit;
